"use client";

import { useState, useTransition } from "react";
import { deleteProduct, quickUpdateProduct } from "@/app/admin/actions";

export function StockInput({ id, stock }: { id: string; stock: number }) {
  const [v, setV] = useState(String(stock));
  const [pending, start] = useTransition();
  return (
    <input
      type="number"
      min={0}
      value={v}
      disabled={pending}
      onChange={(e) => setV(e.target.value)}
      onBlur={() => Number(v) !== stock && start(() => quickUpdateProduct(id, { stock: Number(v) }))}
      onKeyDown={(e) => e.key === "Enter" && (e.target as HTMLInputElement).blur()}
      className="w-20 rounded border border-line px-2 py-1 text-sm tabular-nums"
      aria-label="Stock"
    />
  );
}

export function PriceInput({ id, price }: { id: string; price: number }) {
  const [v, setV] = useState(String(price / 100));
  const [pending, start] = useTransition();
  return (
    <span className="inline-flex items-center gap-1">₹
      <input
        type="number"
        min={1}
        step="0.01"
        value={v}
        disabled={pending}
        onChange={(e) => setV(e.target.value)}
        onBlur={() => Number(v) * 100 !== price && Number(v) > 0 && start(() => quickUpdateProduct(id, { price: Number(v) }))}
        onKeyDown={(e) => e.key === "Enter" && (e.target as HTMLInputElement).blur()}
        className="w-24 rounded border border-line px-2 py-1 text-sm tabular-nums"
        aria-label="Price"
      />
    </span>
  );
}

export function ToggleSwitch({ id, field, value, label }: { id: string; field: "isActive" | "isFeatured"; value: boolean; label: string }) {
  const [pending, start] = useTransition();
  return (
    <button
      type="button"
      role="switch"
      aria-checked={value}
      aria-label={label}
      disabled={pending}
      onClick={() => start(() => quickUpdateProduct(id, { [field]: !value }))}
      className={`relative h-5 w-9 rounded-full transition ${value ? "bg-success" : "bg-line"}`}
    >
      <span className={`absolute top-0.5 h-4 w-4 rounded-full bg-white shadow transition ${value ? "left-4" : "left-0.5"}`} />
    </button>
  );
}

export function DeleteProductButton({ id, name }: { id: string; name: string }) {
  const [pending, start] = useTransition();
  return (
    <button
      type="button"
      disabled={pending}
      onClick={() => confirm(`Delete "${name}"? Products with past orders are archived instead.`) && start(() => deleteProduct(id))}
      className="text-xs text-danger hover:underline"
    >
      Delete
    </button>
  );
}
